#!/bin/bash
# Regenerate patches/xorg-server-1.19.7-riscos.diff from the working tree in
# build/, against an untouched copy in build/pristine/, and check that it
# reproduces the tree. Only hand-edited files are listed: configure, the
# Makefile.in files and the rest of the build system are regenerated by
# build-xserver.sh.
set -euo pipefail
cd "$(dirname "$0")/build"
V=xorg-server-1.19.7
OUT=../patches/$V-riscos.diff
files=(
    xkb/ddxLoad.c os/utils.c os/ospoll.c dix/dispatch.c
    configure.ac hw/kdrive/Makefile.am
    hw/kdrive/riscos/Makefile.am hw/kdrive/riscos/riscos.h
    hw/kdrive/riscos/riscos.c hw/kdrive/riscos/mouse.c
    hw/kdrive/riscos/kbd.c hw/kdrive/riscos/os.c hw/kdrive/riscos/cursor.c
    hw/kdrive/riscos/riscosinit.c hw/kdrive/riscos/iconbar.c
    hw/kdrive/riscos/vcache.c hw/kdrive/riscos/xlogo.h
    hw/kdrive/riscos/rootless.c hw/kdrive/riscos/options.c
    fb/fbpict.c miext/rootless/rootlessScreen.c
    miext/rootless/rootlessCommon.h
)
[ -d "pristine/$V" ] || { mkdir -p pristine; tar xf "../sources/$V.tar.bz2" -C pristine; }
: > "$OUT"
for f in "${files[@]}"; do
    diff -uN "pristine/$V/$f" "$V/$f" |
        sed "1s|^--- pristine/$V/|--- a/|; 2s|^+++ $V/|+++ b/|" >> "$OUT" || true
done
rm -rf patchcheck
cp -a "pristine/$V" patchcheck
patch -s -d patchcheck -p1 < "$OUT"
for f in "${files[@]}"; do
    cmp -s "patchcheck/$f" "$V/$f" || { echo "patch does not reproduce $f"; exit 1; }
done
rm -rf patchcheck
echo "$OUT: $(grep -c '^+++ ' "$OUT") files, reproduces the tree"
